@Service
public class JournalToolExecutor {
  private final ObjectMapper json; private final UserSettingsRepository settings; private final FoodEntryRepository entries; private final FoodItemRepository items;
  private final PrivateFoodRepository privateFoods; private final NutritionResolver nutrition; private final DailyStatusService dailyStatus; private final PendingAgentActionRepository pending; private final JournalUndoActionRepository undo;
  private final OpenFoodFactsClient packagedFoods; private final PendingNutritionQuoteRepository quotes; private final NutritionSourceCacheRepository cache; private final JournalChangeSetRepository changeSets;
  private final SearxngClient searxng; private final BrowserlessClient browserless;
  @org.springframework.beans.factory.annotation.Autowired public JournalToolExecutor(ObjectMapper json, UserSettingsRepository settings, FoodEntryRepository entries, FoodItemRepository items, PrivateFoodRepository privateFoods, NutritionResolver nutrition, DailyStatusService dailyStatus, PendingAgentActionRepository pending, OpenFoodFactsClient packagedFoods, PendingNutritionQuoteRepository quotes, NutritionSourceCacheRepository cache, JournalUndoActionRepository undo, JournalChangeSetRepository changeSets, SearxngClient searxng, BrowserlessClient browserless) { this.json=json;this.settings=settings;this.entries=entries;this.items=items;this.privateFoods=privateFoods;this.nutrition=nutrition;this.dailyStatus=dailyStatus;this.pending=pending;this.packagedFoods=packagedFoods;this.quotes=quotes;this.cache=cache;this.undo=undo;this.changeSets=changeSets;this.searxng=searxng;this.browserless=browserless; }
  public JournalToolExecutor(ObjectMapper json, UserSettingsRepository settings, FoodEntryRepository entries, FoodItemRepository items, PrivateFoodRepository privateFoods, NutritionResolver nutrition, DailyStatusService dailyStatus, PendingAgentActionRepository pending, OpenFoodFactsClient packagedFoods, PendingNutritionQuoteRepository quotes, NutritionSourceCacheRepository cache, JournalUndoActionRepository undo) { this(json,settings,entries,items,privateFoods,nutrition,dailyStatus,pending,packagedFoods,quotes,cache,undo,null,null,null); }
  /** Kept for focused unit tests that do not exercise quote-backed nutrition. */
  public JournalToolExecutor(ObjectMapper json, UserSettingsRepository settings, FoodEntryRepository entries, FoodItemRepository items, PrivateFoodRepository privateFoods, NutritionResolver nutrition, DailyStatusService dailyStatus, PendingAgentActionRepository pending) { this(json,settings,entries,items,privateFoods,nutrition,dailyStatus,pending,null,null,null,null); }
  public JournalToolExecutor(ObjectMapper json, UserSettingsRepository settings, FoodEntryRepository entries, FoodItemRepository items, PrivateFoodRepository privateFoods, NutritionResolver nutrition, DailyStatusService dailyStatus, PendingAgentActionRepository pending, OpenFoodFactsClient packagedFoods, PendingNutritionQuoteRepository quotes, NutritionSourceCacheRepository cache) { this(json,settings,entries,items,privateFoods,nutrition,dailyStatus,pending,packagedFoods,quotes,cache,null); }

  @Transactional(noRollbackFor=AgentToolFailure.class) public AgentToolResult execute(AgentContext c, JournalAgentModel.ToolCall call, List<String> todos) {
    try { Map<String,Object> a=json.readValue(call.arguments()==null?"{}":call.arguments(),new TypeReference<>(){}); return switch(call.name()) {
      case "get_today_summary" -> today(c); case "search_entries" -> search(c,a); case "get_entry" -> entry(c,a); case "get_settings" -> settings(c);
      case "resolve_nutrition", "lookup_food" -> resolve(c,a); case "search_packaged_food" -> packagedFood(c,a); case "get_pending_nutrition_quotes" -> pendingQuotes(c);
      case "search_web" -> searchWeb(a); case "fetch_web_page" -> fetchWebPage(a);
      case "select_packaged_food" -> selectPackaged(c,a); case "get_private_food" -> privateFood(c,a); case "plan_todos" -> planTodos(a,todos); case "complete_todo" -> completeTodo(a,todos);
      case "apply_journal_actions" -> applyActions(c,a); case "undo_last_change" -> undoLast(c); case "create_food_entry" -> create(c,a); case "estimate_food" -> estimateFood(c,a); case "save_private_food" -> savePrivate(c,a); case "update_settings" -> updateSettings(c,a);
      default -> AgentToolResult.failure("VALIDATION_ERROR","That tool is not available.");
    }; } catch (JsonProcessingException | IllegalArgumentException e) { throw new AgentToolFailure(AgentToolResult.failure("VALIDATION_ERROR", "The supplied details are invalid.")); }
  }
  private AgentToolResult planTodos(Map<String,Object>a,List<String> todos){Object raw=a.get("todos");if(!(raw instanceof List<?> list))return AgentToolResult.failure("VALIDATION_ERROR","Provide a short todo list.");todos.clear();for(Object value:list)if(value!=null&&!String.valueOf(value).isBlank()&&todos.size()<6)todos.add(String.valueOf(value));return AgentToolResult.ok(Map.of("todos",List.copyOf(todos)));}
  private AgentToolResult completeTodo(Map<String,Object>a,List<String> todos){String todo=str(a,"todo");if(todo==null||!todos.remove(todo))return AgentToolResult.failure("NOT_FOUND","That todo is not in the current run.");return AgentToolResult.ok(Map.of("todos",List.copyOf(todos)));}
  private AgentToolResult today(AgentContext c){List<FoodEntry> rows=forToday(c.user());int total=rows.stream().map(FoodEntry::getCalories).filter(Objects::nonNull).mapToInt(Integer::intValue).sum();Integer target=profile(c).getCalorieTarget();return AgentToolResult.ok(Map.of("calories",total,"entries",rows.size(),"target",target==null?"unset":target));}
  private AgentToolResult search(AgentContext c,Map<String,Object>a){String q=str(a,"query");String date=str(a,"date");String from=str(a,"fromDate");String to=str(a,"toDate");List<FoodEntry> rows;if(date!=null&&!date.isBlank()){LocalDate day=searchDate(c,date);rows=entriesForPeriod(c,day,day.plusDays(1));}else if((from!=null&&!from.isBlank())||(to!=null&&!to.isBlank())){LocalDate start=searchDate(c,from==null||from.isBlank()?to:from);LocalDate end=searchDate(c,to==null||to.isBlank()?from:to);if(end.isBefore(start))return AgentToolResult.failure("VALIDATION_ERROR","The end date cannot be before the start date.");rows=entriesForPeriod(c,start,end.plusDays(1));}else rows=q==null||q.isBlank()?forToday(c.user()):entries.searchByUserAndTerm(c.user(),q);if(q!=null&&!q.isBlank()&&(date!=null||from!=null||to!=null)){String needle=q.toLowerCase(Locale.ROOT);rows=rows.stream().filter(entry->entry.getOriginalMessage().toLowerCase(Locale.ROOT).contains(needle)).toList();}return AgentToolResult.ok(Map.of("entries",rows.stream().limit(10).map(this::summary).toList()));}
  private AgentToolResult entry(AgentContext c,Map<String,Object>a){return entries.findByIdAndUser(number(a,"entryId").longValue(),c.user()).<AgentToolResult>map(e->AgentToolResult.ok(Map.of("entry",summary(e)))).orElse(AgentToolResult.failure("NOT_FOUND","No matching journal entry exists."));}
  private AgentToolResult settings(AgentContext c){UserSettings s=profile(c);return AgentToolResult.ok(Map.of("timezone",s.getTimezone(),"calorieTarget",s.getCalorieTarget()==null?"unset":s.getCalorieTarget(),"reportsEnabled",s.isReportsEnabled()));}
  private AgentToolResult resolve(AgentContext c,Map<String,Object>a){JournalIntent.MealItem requested=mealItem(a);NutritionResolver.ResolvedMealItem r=nutrition.resolve(c.user(),requested);JournalIntent.MealItem i=r.item();if(i==null||i.totalCalories()==null)return AgentToolResult.failure("NOT_FOUND","Nutrition could not be resolved; search packaged food or estimate it.");return AgentToolResult.ok(Map.of("name",i.name(),"grams",i.grams(),"totalCalories",i.totalCalories(),"caloriesPer100g",i.caloriesPer100g()==null?"unknown":i.caloriesPer100g(),"source",r.source()));}
  private AgentToolResult privateFood(AgentContext c,Map<String,Object>a){String name=str(a,"name");return privateFoods.findByUserAndNameIgnoreCase(c.user(),name).<AgentToolResult>map(p->AgentToolResult.ok(Map.of("name",p.getName(),"caloriesPer100g",p.getCaloriesPer100g()))).orElse(AgentToolResult.failure("NOT_FOUND","No household food matches that name."));}
  private AgentToolResult packagedFood(AgentContext c,Map<String,Object>a){
    if(packagedFoods==null||quotes==null)return AgentToolResult.failure("TEMPORARY_FAILURE","Packaged-food search is unavailable."); String name=str(a,"name"); Double grams=decimalNumber(a,"grams");
    if(name==null||name.isBlank()||grams==null||grams<=0)return AgentToolResult.failure("VALIDATION_ERROR","A food name and positive grams are required.");
    UUID batchId=UUID.randomUUID(); List<Map<String,Object>> products=new ArrayList<>(); for(OpenFoodFactsClient.PackagedFoodResult p:packagedFoods.searchByName(name,str(a,"brand"))){PendingNutritionQuote q=quotes.save(PendingNutritionQuote.packaged(c.user(),batchId,p.productName(),p.brand(),grams,p.caloriesPer100g(),p.barcode(),p.sourceUrl(),Instant.now()));products.add(quoteSummary(q));}
    return products.isEmpty()?AgentToolResult.failure("NOT_FOUND","No usable packaged-food result was found."):AgentToolResult.ok(Map.of("products",products));
  }
  private AgentToolResult searchWeb(Map<String,Object>a){
    if(searxng==null)return AgentToolResult.failure("TEMPORARY_FAILURE","Web search is unavailable.");
    String query=str(a,"query");if(query==null||query.isBlank())return AgentToolResult.failure("VALIDATION_ERROR","A search query is required.");
    List<Map<String,Object>> results=searxng.search(query).stream().map(r->Map.<String,Object>of("title",r.title(),"url",r.url(),"snippet",r.snippet())).toList();
    return results.isEmpty()?AgentToolResult.failure("NOT_FOUND","No web results were found."):AgentToolResult.ok(Map.of("results",results));
  }
  private AgentToolResult fetchWebPage(Map<String,Object>a){
    if(browserless==null)return AgentToolResult.failure("TEMPORARY_FAILURE","Web page fetch is unavailable.");
    String url=str(a,"url");if(url==null||url.isBlank())return AgentToolResult.failure("VALIDATION_ERROR","A url is required.");
    if(!isSafeExternalUrl(url))return AgentToolResult.failure("VALIDATION_ERROR","That url cannot be fetched.");
    return browserless.fetchText(url).<AgentToolResult>map(text->AgentToolResult.ok(Map.of("url",url,"text",text))).orElse(AgentToolResult.failure("NOT_FOUND","That page could not be fetched."));
  }
  private boolean isSafeExternalUrl(String url){
    try{
      URI uri=URI.create(url);String scheme=uri.getScheme();
      if(scheme==null||!(scheme.equalsIgnoreCase("http")||scheme.equalsIgnoreCase("https")))return false;
      String host=uri.getHost();if(host==null||host.isBlank())return false;
      InetAddress address=InetAddress.getByName(host);
      return !(address.isLoopbackAddress()||address.isSiteLocalAddress()||address.isLinkLocalAddress()||address.isAnyLocalAddress());
    }catch(Exception e){return false;}
  }
  private AgentToolResult pendingQuotes(AgentContext c){if(quotes==null)return AgentToolResult.failure("TEMPORARY_FAILURE","Nutrition choices are unavailable.");Instant now=Instant.now();List<Map<String,Object>> rows=quotes.findFirstByUserAndTypeAndExpiresAtAfterOrderByCreatedAtDesc(c.user(),PendingNutritionQuote.Type.PACKAGED_MATCH,now).map(q->quotes.findByUserAndBatchIdAndExpiresAtAfterOrderByCreatedAtAsc(c.user(),q.getBatchId(),now).stream().map(this::quoteSummary).toList()).orElse(List.of());return rows.isEmpty()?AgentToolResult.failure("NOT_FOUND","There are no pending nutrition choices."):AgentToolResult.ok(Map.of("quotes",rows));}
  private AgentToolResult selectPackaged(AgentContext c,Map<String,Object>a){PendingNutritionQuote q=ownedQuote(c,quoteId(a),PendingNutritionQuote.Type.PACKAGED_MATCH);if(q==null)return AgentToolResult.failure("NOT_FOUND","That packaged-food choice is unavailable or expired.");return AgentToolResult.ok(Map.of("quoteId",q.getId().toString(),"item",itemSummary(quoteItem(q),"open_food_facts_estimate","estimate"),"source","Open Food Facts"));}
  private AgentToolResult estimateFood(AgentContext c,Map<String,Object>a){if(quotes==null)return AgentToolResult.failure("TEMPORARY_FAILURE","Nutrition estimates are unavailable.");JournalIntent.MealItem item=mealItem(a);if(!validItem(item)||!validCaloriesPer100g(item.caloriesPer100g()))return AgentToolResult.failure("VALIDATION_ERROR","An estimate needs a food name, positive grams, and calories per 100 g between 1 and 10000.");String basis=Optional.ofNullable(str(a,"basis")).filter(v->!v.isBlank()).orElse("AI estimate");PendingNutritionQuote q=quotes.save(PendingNutritionQuote.estimate(c.user(),item.name(),item.grams(),item.caloriesPer100g(),basis,Instant.now()));return AgentToolResult.ok(Map.of("quoteId",q.getId().toString(),"item",itemSummary(quoteItem(q),"ai_estimate","estimate"),"basis",basis));}
  private AgentToolResult applyActions(AgentContext c,Map<String,Object>a){
    Object rawActions=a.get("actions");if(!(rawActions instanceof List<?> requested)||requested.isEmpty())return AgentToolResult.failure("VALIDATION_ERROR","At least one journal action is required.");
    if(requested.size()>20)return AgentToolResult.failure("VALIDATION_ERROR","A message may contain at most 20 journal actions.");
    Instant now=c.startedAt()==null?Instant.now():c.startedAt();if(changeSets!=null)changeSets.deleteByExpiresAtBefore(now);JournalChangeSet changeSet=changeSets==null?null:JournalChangeSet.start(c.user(),now);List<Map<String,Object>> results=new ArrayList<>();int changed=0;
    for(Object value:requested){if(!(value instanceof Map<?,?> raw)){results.add(actionFailure("ACTION","Invalid journal action."));continue;}Map<String,Object> action=new LinkedHashMap<>();raw.forEach((key,item)->action.put(String.valueOf(key),item));String type=Optional.ofNullable(str(action,"type")).orElse("ACTION").toUpperCase(Locale.ROOT);try{Map<String,Object> result=applyOne(c,type,action,changeSet,now);if(Boolean.TRUE.equals(result.get("ok"))){entries.flush();items.flush();changed++;}results.add(result);}catch(AgentToolFailure failure){results.add(actionFailure(type,Optional.ofNullable(failure.result().userHint()).orElse("The action was rejected.")));}catch(IllegalArgumentException failure){results.add(actionFailure(type,Optional.ofNullable(failure.getMessage()).orElse("The action details are invalid.")));}}
    if(changed>0){if(changeSet!=null)changeSets.saveAndFlush(changeSet);dailyStatus.refresh(c.user(),c.chatId());}
    Map<String,Object> data=new LinkedHashMap<>();data.put("results",results);data.put("successful",changed);data.put("failed",results.size()-changed);data.put("undoAvailable",changed>0&&changeSet!=null);return AgentToolResult.ok(Map.copyOf(data));
  }
  private Map<String,Object> applyOne(AgentContext c,String type,Map<String,Object>a,JournalChangeSet changeSet,Instant now){return switch(type){case "CREATE"->createAction(c,a,changeSet,now);case "EDIT"->editAction(c,a,changeSet);case "MOVE"->moveAction(c,a,changeSet);case "DELETE"->deleteAction(c,a,changeSet,now);default->actionFailure(type,"Unsupported journal action.");};}
  private Map<String,Object> createAction(AgentContext c,Map<String,Object>a,JournalChangeSet changeSet,Instant now){
    String description=Optional.ofNullable(str(a,"description")).orElse(str(a,"name"));if(description==null||description.isBlank())throw new IllegalArgumentException("A description is required.");
    Integer calories=a.containsKey("calories")?number(a,"calories"):null;String source=normalizeSource(str(a,"nutritionSource"),"manual");String confidence=normalizeConfidence(str(a,"nutritionConfidence"),"manual".equals(source)?"high":"estimate");Double quantity=decimalNumber(a,"quantity");QuantityUnit unit=quantityUnit(str(a,"unit"),quantity);List<PendingNutritionQuote> consumed=new ArrayList<>();
    if(a.get("quoteId")!=null){UUID id=quoteId(a);PendingNutritionQuote quote=quotes==null||id==null?null:quotes.lockOwnedActive(id,c.user(),Instant.now()).orElse(null);if(quote==null)throw new AgentToolFailure(AgentToolResult.failure("NOT_FOUND","The selected nutrition result is unavailable or expired."));JournalIntent.MealItem quoted=quoteItem(quote);calories=quoted.totalCalories();quantity=quoted.grams();unit=QuantityUnit.G;description=Optional.ofNullable(description).filter(v->!v.isBlank()).orElse(quoted.name());source=sourceFor(quote.getType()==PendingNutritionQuote.Type.PACKAGED_MATCH?NutritionMode.PACKAGED_MATCH:NutritionMode.AI_ESTIMATE);confidence="estimate";consumed.add(quote);}
    if(calories==null||calories<=0||calories>10000)throw new IllegalArgumentException("Calories must be between 1 and 10000.");if(quantity!=null&&(!Double.isFinite(quantity)||quantity<=0||quantity>100000d))throw new IllegalArgumentException("Quantity must be positive.");
    Instant eatenAt=resolveMealInstant(c,str(a,"date"),str(a,"localTime"));FoodEntry saved=entries.save(new FoodEntry(c.user(),description,eatenAt,calories,source,confidence));FoodItem foodItem=items.save(new FoodItem(saved,description,quantity==null?null:BigDecimal.valueOf(quantity),unit,calories,null,null,null,source,confidence));
    for(PendingNutritionQuote quote:consumed){if(quote.getType()==PendingNutritionQuote.Type.PACKAGED_MATCH)cacheSelected(quote);quotes.delete(quote);}JournalEntrySnapshot after=JournalEntrySnapshot.capture(saved,List.of(foodItem));if(changeSet!=null)changeSet.addMutation(JournalMutationType.CREATE,null,after);return actionSuccess("CREATE",saved,c);
  }
  private Map<String,Object> editAction(AgentContext c,Map<String,Object>a,JournalChangeSet changeSet){FoodEntry entry=ownedEntry(c,a);List<FoodItem> current=items.findByEntry(entry);JournalEntrySnapshot before=JournalEntrySnapshot.capture(entry,current);String description=Optional.ofNullable(str(a,"description")).filter(v->!v.isBlank()).orElse(entry.getOriginalMessage());Integer calories=a.containsKey("calories")?number(a,"calories"):entry.getCalories();if(calories==null||calories<0||calories>10000)throw new IllegalArgumentException("Calories must be between 0 and 10000.");entry.revise(description,calories);synchronizeItemsAfterEdit(current,description,calories);JournalEntrySnapshot after=JournalEntrySnapshot.capture(entry,current);if(changeSet!=null)changeSet.addMutation(JournalMutationType.EDIT,before,after);return actionSuccess("EDIT",entry,c);}
  private void synchronizeItemsAfterEdit(List<FoodItem> current,String description,int totalCalories){if(current.isEmpty())return;if(current.size()==1){current.getFirst().revise(description,totalCalories);return;}int oldTotal=current.stream().map(FoodItem::getCalories).filter(Objects::nonNull).mapToInt(Integer::intValue).sum();int assigned=0;for(int index=0;index<current.size();index++){FoodItem item=current.get(index);int revised=index==current.size()-1?totalCalories-assigned:oldTotal<=0?0:(int)Math.floor(totalCalories*(Math.max(0,Optional.ofNullable(item.getCalories()).orElse(0))/(double)oldTotal));revised=Math.max(0,Math.min(10000,revised));assigned+=revised;item.reviseCalories(revised);}}
  private Map<String,Object> moveAction(AgentContext c,Map<String,Object>a,JournalChangeSet changeSet){FoodEntry entry=ownedEntry(c,a);List<FoodItem> current=items.findByEntry(entry);JournalEntrySnapshot before=JournalEntrySnapshot.capture(entry,current);entry.moveTo(resolveMealInstant(c,str(a,"date"),str(a,"localTime"),entry.getEatenAt()));JournalEntrySnapshot after=JournalEntrySnapshot.capture(entry,current);if(changeSet!=null)changeSet.addMutation(JournalMutationType.MOVE,before,after);return actionSuccess("MOVE",entry,c);}
  private Map<String,Object> deleteAction(AgentContext c,Map<String,Object>a,JournalChangeSet changeSet,Instant now){FoodEntry entry=ownedEntry(c,a);List<FoodItem> current=items.findByEntry(entry);JournalEntrySnapshot before=JournalEntrySnapshot.capture(entry,current);entry.markDeleted(now);JournalEntrySnapshot after=JournalEntrySnapshot.capture(entry,current);if(changeSet!=null)changeSet.addMutation(JournalMutationType.DELETE,before,after);return actionSuccess("DELETE",entry,c);}
  private FoodEntry ownedEntry(AgentContext c,Map<String,Object>a){if(!a.containsKey("entryId"))throw new IllegalArgumentException("An entry ID is required.");return entries.findByIdAndUser(number(a,"entryId").longValue(),c.user()).orElseThrow(()->new AgentToolFailure(AgentToolResult.failure("NOT_FOUND","No matching journal entry exists.")));}
  private Map<String,Object> actionSuccess(String type,FoodEntry entry,AgentContext c){Map<String,Object> result=new LinkedHashMap<>();result.put("ok",true);result.put("type",type);result.put("entry",summary(entry));result.put("date",entry.getEatenAt().atZone(ZoneId.of(profile(c).getTimezone())).toLocalDate().toString());return Map.copyOf(result);}
  private Map<String,Object> actionFailure(String type,String message){return Map.of("ok",false,"type",type,"message",message);}
  private AgentToolResult undoLast(AgentContext c){if(changeSets==null)return AgentToolResult.failure("NOT_FOUND","There is no recent journal change to undo.");Instant now=c.startedAt()==null?Instant.now():c.startedAt();JournalChangeSet set=changeSets.findFirstByUserAndUndoneAtIsNullAndExpiresAtAfterOrderByCreatedAtDescIdDesc(c.user(),now).orElse(null);if(set==null)return AgentToolResult.failure("NOT_FOUND","There is no recent journal change to undo.");List<JournalMutation> mutations=new ArrayList<>(set.getMutations());Collections.reverse(mutations);for(JournalMutation mutation:mutations){JournalEntrySnapshot before=mutation.getBeforeState();JournalEntrySnapshot after=mutation.getAfterState();Long entryId=before==null?after.entryId():before.entryId();FoodEntry entry=entries.findIncludingDeletedByIdAndUser(entryId,c.user()).orElse(null);if(entry==null)continue;if(mutation.getActionType()==JournalMutationType.CREATE){entry.markDeleted(now);continue;}entry.restoreFrom(before);items.deleteByEntry(entry);for(JournalEntrySnapshot.FoodItemSnapshot item:before.items())items.save(item.recreateFor(entry));}set.markUndone(now);dailyStatus.refresh(c.user(),c.chatId());return AgentToolResult.ok(Map.of("changeSetId",set.getId()==null?"pending":set.getId(),"actions",mutations.size()));}
  private AgentToolResult create(AgentContext c,Map<String,Object>a){
    List<Map<String,Object>> raw=json.convertValue(a.get("items"),new TypeReference<>(){});if(raw==null||raw.isEmpty())return AgentToolResult.failure("VALIDATION_ERROR","At least one food item is required.");Set<UUID> quoteIds=new HashSet<>();for(Map<String,Object> row:raw){NutritionMode mode=nutritionMode(row);if(mode!=NutritionMode.DECLARED){UUID id=quoteId(row);if(id==null||!quoteIds.add(id))return AgentToolResult.failure("VALIDATION_ERROR","Each nutrition quote may be used only once.");}}List<PersistedItem> resolved=new ArrayList<>();List<PendingNutritionQuote> consumed=new ArrayList<>();
    for(Map<String,Object> row:raw){NutritionMode mode=nutritionMode(row);if(mode==NutritionMode.DECLARED){JournalIntent.MealItem requested=mealItem(row);if(!validItem(requested))return AgentToolResult.failure("VALIDATION_ERROR","Each item needs a name and a positive gram quantity.");NutritionResolver.ResolvedMealItem r=nutrition.resolve(c.user(),requested);JournalIntent.MealItem item=r.item();if(item==null||item.totalCalories()==null)return AgentToolResult.failure("VALIDATION_ERROR","One item needs calories per 100 g, total calories, a barcode, or a saved household food.");if(item.totalCalories()<=0||item.totalCalories()>10000)return AgentToolResult.failure("VALIDATION_ERROR","One item has an invalid calorie value.");resolved.add(new PersistedItem(item,"manual","high"));}
      else {UUID id=quoteId(row);PendingNutritionQuote.Type expected=mode==NutritionMode.PACKAGED_MATCH?PendingNutritionQuote.Type.PACKAGED_MATCH:PendingNutritionQuote.Type.AI_ESTIMATE;PendingNutritionQuote q=ownedQuote(c,id,expected);if(q==null)return AgentToolResult.failure("NOT_FOUND","That nutrition quote is unavailable, expired, or belongs to another user.");JournalIntent.MealItem item=quoteItem(q);resolved.add(new PersistedItem(item,sourceFor(mode),"estimate"));consumed.add(q);}
    }
    int total=resolved.stream().map(PersistedItem::item).mapToInt(i->i.totalCalories()).sum();if(total<=0||total>10000)return AgentToolResult.failure("VALIDATION_ERROR","The meal calorie total is outside the allowed range.");String source=resolved.stream().map(PersistedItem::source).distinct().count()==1?resolved.getFirst().source():"mixed";String confidence=resolved.stream().allMatch(i->"high".equals(i.confidence()))?"high":"estimate";FoodEntry saved=entries.save(new FoodEntry(c.user(),originalMealMessage(c.message()),Instant.now(),total,source,confidence));for(PersistedItem r:resolved){JournalIntent.MealItem i=r.item();items.save(new FoodItem(saved,i.name(),BigDecimal.valueOf(i.grams()),i.totalCalories(),decimal(i.proteinGrams()),decimal(i.carbsGrams()),decimal(i.fatGrams()),r.source(),r.confidence()));}
    for(PendingNutritionQuote q:consumed){if(q.getType()==PendingNutritionQuote.Type.PACKAGED_MATCH)cacheSelected(q);quotes.delete(q);}dailyStatus.refresh(c.user(),c.chatId());return AgentToolResult.ok(Map.of("entry",summary(saved),"today",today(c).data(),"estimated",!"high".equals(confidence)));
  }
  private void cacheSelected(PendingNutritionQuote q){if(cache==null||q.getBarcode()==null||q.getBarcode().isBlank())return;NutritionSourceCache existing=cache.findByBarcode(q.getBarcode()).orElse(null);if(existing==null)cache.save(new NutritionSourceCache(q.getBarcode(),q.getProductName(),q.getCaloriesPer100g(),null,null,null,q.getSourceUrl(),Instant.now()));else existing.refresh(q.getProductName(),q.getCaloriesPer100g(),null,null,null,q.getSourceUrl(),Instant.now());}
  private PendingNutritionQuote ownedQuote(AgentContext c,UUID id,PendingNutritionQuote.Type type){if(quotes==null||id==null)return null;return quotes.lockOwnedActive(id,c.user(),Instant.now()).filter(q->q.getType()==type).orElse(null);}
  private JournalIntent.MealItem quoteItem(PendingNutritionQuote q){return withCalculatedCalories(new JournalIntent.MealItem(q.getProductName(),q.getGrams(),null,q.getCaloriesPer100g(),null,null,null,q.getBarcode()));}
  private Map<String,Object> quoteSummary(PendingNutritionQuote q){Map<String,Object> m=new LinkedHashMap<>();m.put("quoteId",q.getId().toString());m.put("name",q.getProductName());m.put("brand",q.getBrand());m.put("grams",q.getGrams());m.put("caloriesPer100g",q.getCaloriesPer100g());m.put("totalCalories",quoteItem(q).totalCalories());m.put("type",q.getType().name());if(q.getBarcode()!=null)m.put("barcode",q.getBarcode());if(q.getSourceUrl()!=null)m.put("sourceUrl",q.getSourceUrl());return m;}
  private AgentToolResult savePrivate(AgentContext c,Map<String,Object>a){String name=str(a,"name");Integer kcal=number(a,"caloriesPer100g");if(name==null||name.isBlank()||kcal<0||kcal>10000)return AgentToolResult.failure("VALIDATION_ERROR","A food name and valid calories per 100 g are required.");PrivateFood p=privateFoods.findByUserAndNameIgnoreCase(c.user(),name).orElse(null);if(p==null)privateFoods.save(new PrivateFood(c.user(),name,kcal,null,null,null));else p.refresh(kcal,null,null,null);return AgentToolResult.ok(Map.of("name",name,"caloriesPer100g",kcal));}
  private AgentToolResult updateSettings(AgentContext c,Map<String,Object>a){String timezone=null;Integer target=null;Boolean reports=null;if(a.containsKey("timezone")){try{timezone=ZoneId.of(str(a,"timezone")).getId();}catch(Exception x){return AgentToolResult.failure("VALIDATION_ERROR","Use a valid IANA timezone.");}}if(a.containsKey("calorieTarget")){target=number(a,"calorieTarget");if(target<1200||target>5000)return AgentToolResult.failure("VALIDATION_ERROR","The calorie target must be 1200-5000.");}if(a.containsKey("reportsEnabled")){String value=String.valueOf(a.get("reportsEnabled"));if(!"true".equalsIgnoreCase(value)&&!"false".equalsIgnoreCase(value))return AgentToolResult.failure("VALIDATION_ERROR","reportsEnabled must be true or false.");reports=Boolean.valueOf(value);}UserSettings s=profile(c);if(timezone!=null)s.setTimezone(timezone);if(target!=null)s.setCalorieTarget(target);if(reports!=null)s.setReportsEnabled(reports);return settings(c);}
  private Instant resolveMealInstant(AgentContext c,String requestedDate,String requestedTime){return resolveMealInstant(c,requestedDate,requestedTime,null);}
  private LocalDate searchDate(AgentContext c,String requested){ZoneId zone=ZoneId.of(profile(c).getTimezone());LocalDate today=(c.startedAt()==null?Instant.now():c.startedAt()).atZone(zone).toLocalDate();String value=requested==null?"today":requested.trim().toLowerCase(Locale.ROOT);if(Set.of("today","azi","astăzi","astazi").contains(value))return today;if(Set.of("yesterday","yersterday","ieri").contains(value))return today.minusDays(1);try{return LocalDate.parse(value);}catch(Exception failure){throw new IllegalArgumentException("Use today, yesterday, or an ISO date.");}}
  private List<FoodEntry> entriesForPeriod(AgentContext c,LocalDate start,LocalDate endExclusive){ZoneId zone=ZoneId.of(profile(c).getTimezone());return entries.findByUserAndEatenAtBetweenOrderByEatenAtAsc(c.user(),start.atStartOfDay(zone).toInstant(),endExclusive.atStartOfDay(zone).toInstant());}
  private Instant resolveMealInstant(AgentContext c,String requestedDate,String requestedTime,Instant existing){ZoneId zone=ZoneId.of(profile(c).getTimezone());Instant base=c.startedAt()==null?Instant.now():c.startedAt();LocalDate today=base.atZone(zone).toLocalDate();String value=requestedDate==null||requestedDate.isBlank()?"today":requestedDate.trim().toLowerCase(Locale.ROOT);LocalDate date;if(Set.of("today","azi","astăzi","astazi").contains(value))date=today;else if(Set.of("yesterday","yersterday","ieri").contains(value))date=today.minusDays(1);else try{date=LocalDate.parse(value);}catch(Exception failure){throw new IllegalArgumentException("Use today, yesterday, or an ISO date.");}if(date.isAfter(today))throw new IllegalArgumentException("Future meal dates are not allowed.");LocalTime time;if(requestedTime!=null&&!requestedTime.isBlank())try{time=LocalTime.parse(requestedTime);}catch(Exception failure){throw new IllegalArgumentException("Use a valid local time such as 18:30.");}else if(existing!=null)time=existing.atZone(zone).toLocalTime();else time=base.atZone(zone).toLocalTime();LocalDateTime local=date.atTime(time);List<ZoneOffset> offsets=zone.getRules().getValidOffsets(local);if(offsets.isEmpty())throw new IllegalArgumentException("That local time does not exist because of daylight-saving time. Use another time.");Instant result=local.toInstant(offsets.getFirst());if(result.isAfter(base))throw new IllegalArgumentException("Future meal times are not allowed.");return result;}
  private QuantityUnit quantityUnit(String raw,Double quantity){if(raw==null||raw.isBlank())return quantity==null?QuantityUnit.UNSPECIFIED:QuantityUnit.PORTION;return QuantityUnit.fromDatabaseValue(raw);}
  private String normalizeSource(String raw,String fallback){String value=raw==null?fallback:raw.toLowerCase(Locale.ROOT);return Set.of("manual","private","open_food_facts_estimate","ai_estimate","mixed").contains(value)?value:fallback;}
  private String normalizeConfidence(String raw,String fallback){String value=raw==null?fallback:raw.toLowerCase(Locale.ROOT);return Set.of("high","estimate","unknown").contains(value)?value:fallback;}
  private String originalMealMessage(String message){String prefix="Estimate this meal now: ";return message!=null&&message.startsWith(prefix)?message.substring(prefix.length()):message;} private UserSettings profile(AgentContext c){return settings.findById(c.user().getId()).orElseThrow();} private List<FoodEntry> forToday(FoodUser u){ZoneId z=ZoneId.of(settings.findById(u.getId()).orElseThrow().getTimezone());LocalDate d=LocalDate.now(z);return entries.findByUserAndEatenAtBetweenOrderByEatenAtAsc(u,d.atStartOfDay(z).toInstant(),d.plusDays(1).atStartOfDay(z).toInstant());} private Map<String,Object> summary(FoodEntry e){Map<String,Object> value=new LinkedHashMap<>();value.put("id",e.getId());value.put("calories",e.getCalories());value.put("eatenAt",e.getEatenAt().toString());value.put("description",e.getOriginalMessage());return Map.copyOf(value);} private String str(Map<String,Object>a,String key){Object v=a.get(key);return v==null?null:String.valueOf(v);} private Integer number(Map<String,Object>a,String key){Object v=a.get(key);if(v==null)throw new IllegalArgumentException();return v instanceof Number n?n.intValue():Integer.parseInt(String.valueOf(v));} private Double decimalNumber(Map<String,Object>a,String key){Object v=a.get(key);return v==null?null:Double.valueOf(String.valueOf(v));} private UUID quoteId(Map<String,Object>a){try{return UUID.fromString(str(a,"quoteId"));}catch(Exception e){return null;}} private JournalIntent.MealItem mealItem(Map<String,Object>a){return new JournalIntent.MealItem(str(a,"name"),decimalNumber(a,"grams"),a.get("totalCalories")==null?null:number(a,"totalCalories"),a.get("caloriesPer100g")==null?null:number(a,"caloriesPer100g"),null,null,null,str(a,"barcode"));} private BigDecimal decimal(Double v){return v==null?null:BigDecimal.valueOf(v);} private boolean isConfirmation(String message){String m=message==null?"":message.trim().toLowerCase(Locale.ROOT);return Set.of("da","confirm","confirmă","confirma","yes").contains(m);} private Map<String,Object> itemSummary(JournalIntent.MealItem i,String source,String confidence){return Map.of("name",i.name(),"grams",i.grams(),"caloriesPer100g",i.caloriesPer100g(),"totalCalories",i.totalCalories(),"source",source,"confidence",confidence);} private boolean validItem(JournalIntent.MealItem item){return item!=null&&item.name()!=null&&!item.name().isBlank()&&item.grams()!=null&&item.grams()>0;} private boolean validCaloriesPer100g(Integer calories){return calories!=null&&calories>0&&calories<=10000;} private JournalIntent.MealItem withCalculatedCalories(JournalIntent.MealItem item){return new JournalIntent.MealItem(item.name(),item.grams(),(int)Math.round(item.grams()*item.caloriesPer100g()/100d),item.caloriesPer100g(),item.proteinGrams(),item.carbsGrams(),item.fatGrams(),item.barcode());} private NutritionMode nutritionMode(Map<String,Object> row){String value=str(row,"nutritionMode");if(value==null||value.isBlank())return NutritionMode.DECLARED;try{return NutritionMode.valueOf(value.toUpperCase(Locale.ROOT));}catch(IllegalArgumentException e){throw new AgentToolFailure(AgentToolResult.failure("VALIDATION_ERROR","nutritionMode must be DECLARED, PACKAGED_MATCH, or AI_ESTIMATE."));}} private String sourceFor(NutritionMode mode){return switch(mode){case DECLARED->"manual";case PACKAGED_MATCH->"open_food_facts_estimate";case AI_ESTIMATE->"ai_estimate";};} private enum NutritionMode { DECLARED, PACKAGED_MATCH, AI_ESTIMATE } private record PersistedItem(JournalIntent.MealItem item,String source,String confidence) {}
}
